CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE user_progress (id UUID PRIMARY KEY, user_id UUID NOT NULL UNIQUE REFERENCES app_user(id), total_xp INT NOT NULL DEFAULT 0, current_level VARCHAR(40) NOT NULL DEFAULT 'BEGINNER_CHEF', updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE recipe (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id), title VARCHAR(255) NOT NULL, description TEXT NOT NULL, product_type VARCHAR(60) NOT NULL, servings INT NOT NULL, preparation_time INT NOT NULL, cooking_time INT NOT NULL, ingredients_json TEXT NOT NULL, stages_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE cooking_session (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id), recipe_id UUID REFERENCES recipe(id), session_type VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, current_stage INT NOT NULL DEFAULT 0, desired_outcome VARCHAR(500), context_json TEXT, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE cooking_observation (id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES cooking_session(id), image_object_key VARCHAR(500) NOT NULL, observed_state_json TEXT NOT NULL, target_comparison_json TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE cooking_feedback (id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES cooking_session(id), observation_id UUID NOT NULL REFERENCES cooking_observation(id), status VARCHAR(30) NOT NULL, action VARCHAR(30) NOT NULL, action_details_json TEXT, reason_code VARCHAR(80), message_key VARCHAR(80) NOT NULL, resolved_message VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE cooking_action (id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES cooking_session(id), feedback_id UUID NOT NULL REFERENCES cooking_feedback(id), action_description VARCHAR(500) NOT NULL, user_confirmed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE xp_transaction (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id), session_id UUID REFERENCES cooking_session(id), amount INT NOT NULL, reason VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, session_id, reason));
CREATE INDEX idx_recipe_user ON recipe(user_id); CREATE INDEX idx_session_user ON cooking_session(user_id); CREATE INDEX idx_observation_session ON cooking_observation(session_id);
